// accepts is the truncation rule: a file is complete where the state the read
// ends in accepts and its acceptance guards all hold, and truncated otherwise.
//
// Guarded acceptance is what makes the last iteration of a count detectable. A
// state that reads details while a counter is positive would otherwise have to
// accept unconditionally, and would accept a file stopping three details short
// of what its own header promised.
func (r *Reader) accepts() error {
	switch r.state {
	case 8:
		return nil
	default:
		return fmt.Errorf("the file ends after %d records and the layout describes a record to come", r.ordinal)
	}
}

// undescribed is what a state says when none of its transitions took the record
// in front of the reader.
//
// A record excluded by a guard is reported as that rather than as a record the
// layout does not describe, because the two send a reader of the diagnostic to
// different places: the first is a record that does not belong at this point in
// the file, the second a record type the layout is missing.
func (r *Reader) undescribed(expected []string, excluded string) error {
	if excluded != "" {
		return fmt.Errorf("record %d does not belong here: %s", r.ordinal, excluded)
	}

	if len(expected) == 0 {
		return fmt.Errorf("record %d is a record the layout does not describe, and the automaton is in a state admitting none", r.ordinal)
	}

	return fmt.Errorf("record %d is a record the layout does not describe, and the automaton expected one of %s", r.ordinal, strings.Join(expected, ", "))
}

// unbound is a register read before anything wrote it, which is a malformed
// descriptor rather than a zero. A consumer supplying one would read a file
// against a count nobody stated.
func (r *Reader) unbound(node int) error {
	return fmt.Errorf("record %d reads the register the descriptor carries as node %d, and no transition taken before it bound one", r.ordinal+1, node)
}

// leading consumes the framing in front of a record: the record descriptor word DFSMS defines,
// whose length this reader checks against the extent of the record it admits
// rather than taking a record's end from.
//
// Framing bytes belong to the dataset and not to any record: no item covers
// them, they are not slack, and no predicate ever sees one.
func (r *Reader) leading() error {
	var word [4]byte

	if _, err := io.ReadFull(r.src, word[:]); err != nil {
		return fmt.Errorf("the file ends inside the record descriptor word in front of record %d: %v", r.ordinal, err)
	}

	stated := int(word[0])<<8 | int(word[1])
	if stated < 4 {
		return fmt.Errorf("the record descriptor word in front of record %d states %d bytes, and 4 of them are the word itself", r.ordinal, stated)
	}

	r.data = r.data[:0]

	if err := r.fill(stated - 4); err != nil {
		return fmt.Errorf("the file ends part-way through record %d, which its record descriptor word states is %d bytes: %v", r.ordinal, stated-4, err)
	}

	r.look = r.data

	return nil
}

// admit decodes one record and takes its end from its extent.
//
// The input is never searched for a delimiter and a descriptor word's length is
// never preferred to the extent. Scanning is the obvious way to write a
// line-oriented reader and is wrong on exactly these files: a PIC S9(3)V99
// COMP-3 field holding +152.50 is the bytes 15 25 0C, and both 0x15 and 0x25
// are line delimiters on some mainframe code page. A reader counting the extent
// never reads those bytes as anything but the number they are.
func (r *Reader) admit(rec Record) error {
	// The record's bytes are in hand, so the decoder is rewound onto them rather
	// than built over them. A rewind keeps everything the encoding derives and
	// swaps only the bytes, which is a construction and an allocation this
	// reader does not make per record — and it puts the offset back to zero, so
	// every offset codec reports is counted from the start of this record
	// rather than from the start of the file.
	r.cr.Reset(r.data)

	if err := rec.UnmarshalCOBOL(r.cr); err != nil {
		if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
			return fmt.Errorf("the framing states record %d is %d bytes and the extent of the record it admits is longer than that: %v", r.ordinal, len(r.data), err)
		}

		return fmt.Errorf("reading record %d: %w", r.ordinal, err)
	}

	// The framing checked against the extent, which is what a framed file buys
	// over an unframed one: a wrong width or a mis-selected transition is an
	// error at the record it happened on rather than silence. The extent is what
	// the decoder consumed, which is its offset: the rewind above is what makes
	// that a count of this record rather than of the file.
	if r.cr.Offset() != int64(len(r.data)) {
		return fmt.Errorf("the framing states record %d is %d bytes and the extent of the record it admits is %d", r.ordinal, len(r.data), r.cr.Offset())
	}

	return nil
}

// fill appends the next n bytes of the input to the record in hand.
func (r *Reader) fill(n int) error {
	if n < 0 {
		return io.ErrUnexpectedEOF
	}

	at := len(r.data)

	if cap(r.data)-at < n {
		grown := make([]byte, at+n)
		copy(grown, r.data)
		r.data = grown
	}

	r.data = r.data[:at+n]

	_, err := io.ReadFull(r.src, r.data[at:])

	return err
}

// matches77At0 is the predicate selecting transition 1 of the state the descriptor
// carries as node 77: it admits LEDGER-HEADER.
//
// A target that is not wholly inside the bytes it is handed does not match. A
// reader hands it the record the framing bounds, or as much of the input as it
// can see where the framing bounds nothing; a writer hands it the whole of the
// record it is about to emit.
func matches77At0(b []byte) bool {
	if len(b) < 2 {
		return false
	}

	return bytes.Equal(b[0:2], []byte("\xf0\xf1"))
}

