// Writer writes the records of one file, walking the automaton this descriptor
// carries in the other direction.
//
// Its caller names a record and supplies that record's values. It narrows to
// the transitions leaving the state it is in that admit such a record and whose
// guards all hold, evaluates their predicates in the order the state carries
// them, and takes the first that carries no predicate or whose predicate matches
// the bytes it is about to emit. A record satisfying none is reported rather
// than emitted: refusing where the mistake was made costs one diagnostic, and
// emitting costs a file somebody has to read before anyone finds out.
//
// Nothing is buffered beyond the record in hand. A count in a header is never
// back-filled from the records behind it, because holding a group to count it
// gives up exactly the streaming this type exists to have — and because a
// writer that has emitted a record cannot reach back into a stream it does not
// own.
type Writer struct {
	dst io.Writer

	// cw lays out the record in hand, and is the only encoder this writer
	// builds: a predicate is evaluated against the bytes that are about to go
	// out, so a record exists as bytes before the transition carrying it is
	// chosen, and the method emitting a record rewinds this onto it rather
	// than constructing one over it. The buffer those bytes accumulate in is
	// this encoder's own — [codec.Writer.Bytes] is where they are read back —
	// and it is kept at its capacity across every rewind, along with everything
	// the encoding derives. That is why the encoding is not kept beside it:
	// codec.Writer carries it, and one that could be swapped under a half-laid
	// record is what codec refuses to allow.
	cw *codec.Writer

	// state is where in the automaton the write is, numbered as [Reader.state] is.
	state int

	// ordinal is how many records have been written, so that a diagnostic can
	// say where.
	ordinal int

	// The register file. There is one for the whole write, a register holds what the
	// most recent binding put in it, and nothing saves or restores one — so the
	// value in force is the one from the nearest preceding record that bound it,
	// along the path actually taken.
	//
	// Each carries whether anything has bound it, because reading a register
	// nothing has written is a malformed descriptor rather than a zero: a consumer
	// MUST NOT supply a zero, an empty byte string or the value of any other
	// register. See docs/ir/SPEC.md, "The automaton remembers, in registers".
	register76      int64
	register76Bound bool
}

// NewWriter writes records into w under enc.
//
// The five axes are the caller's for the reason they are on [NewReader]: they are
// properties of the file being written rather than of this descriptor's items.
func NewWriter(w io.Writer, enc codec.Encoding) (*Writer, error) {
	if w == nil {
		return nil, codec.ErrNilWriter
	}

	// The one encoder this writer builds, over a buffer of no bytes until the
	// first record is laid into it. Construction is what validates the
	// encoding, and it reports the same error for the same axis that
	// enc.Validate does, so nothing is checked twice here.
	cw, err := codec.NewBytesWriter(nil, enc)
	if err != nil {
		return nil, err
	}

	return &Writer{
		dst:   w,
		cw:    cw,
		state: 0,
	}, nil
}

// Write emits one record.
//
// A value that is not one of this file's record types is reported rather than
// emitted: no transition admits a record the descriptor does not carry, and
// [Record] is satisfied by anything codec can encode.
func (w *Writer) Write(rec Record) error {
	switch v := rec.(type) {
	case *CreditPosting:
		return w.writeCreditPosting(v)
	case *CreditPostingRef:
		return w.writeCreditPostingRef(v)
	case *DebitPosting:
		return w.writeDebitPosting(v)
	case *DebitPostingRef:
		return w.writeDebitPostingRef(v)
	case *LedgerHeader:
		return w.writeLedgerHeader(v)
	case *LedgerTrailer:
		return w.writeLedgerTrailer(v)
	case *MemoPosting:
		return w.writeMemoPosting(v)
	case *MemoPostingRef:
		return w.writeMemoPostingRef(v)
	default:
		return fmt.Errorf("record %d: this file's records are POSTING-RECORD, POSTING-RECORD, POSTING-RECORD, POSTING-RECORD, LEDGER-HEADER, LEDGER-TRAILER, POSTING-RECORD and POSTING-RECORD, and a %T is none of them", w.ordinal+1, rec)
	}
}

// Close ends the file, and reports a state that does not accept — or whose
// acceptance guards do not all hold — rather than closing it.
//
// A group that promised four details and was given three is caught here. It is
// the reader's truncation rule from the other side, and a writer skipping the
// check emits the truncated file its reader complains about one build later.
//
// It does not close the io.Writer it was handed, which belongs to the caller.
func (w *Writer) Close() error {
	switch w.state {
	case 8:
		return nil
	default:
		return fmt.Errorf("the file is closed after %d records and the layout describes a record to come", w.ordinal)
	}
}

